class GenericMeasureStartup(GenericBts):
    """Keywords for eNB and gNB combined from different keyword types e.g. alarm and cell"""

    def __init__(self, bts_type, bbu, alarm, cell, log, ru):
        """
        Constructor of CombinedGenericKeywords class.
        :param bts_type: GNB|ENB
        :param bbu: Object of EnbBbu or GnbBbu
        :param cell: Object of EnbCell or GnbCell class
        """
        super(GenericMeasureStartup, self).__init__(bts_type=bts_type)
        self.bbu = bbu
        self.alarm = alarm
        self.cell = cell
        self.log = log
        self.ru = ru

    def measure_start_up_time(self, bts_id=0, runs=1, target=0.99, time_target=420, timeout=600, du_id=0,
                              raise_exception=True, reset_type="bts_site_reset",
                              radio_unit='all_every_second_iteration',
                              end_measure_time="last_cell_up"):
        """
        Performs provided reset_type given amount of times, checks if site fully recovered and measures start-up time,
        then checks if PASSED to RUNS ratio meets given target.
        :param end_measure_time: first_cell_up or last_cell_up
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param runs: Number of runs
        :param target: Target PASSED to RUNS ratio
        :param time_target: Target start-up time in seconds.
        :param timeout: Wait for onAir after bts reset timeout in seconds.
        :param raise_exception: True/False - raise StartUpTargetNotMet exception if avg/ratio not met targets
        :param reset_type: Way of reset. Available: bts_site_reset, bts_power_reset, bbmod_reset, ru_reset.
        :param radio_unit: ID of radio to reset or 'random' or 'all' or 'all_every_second_iteration'.
                           Applicable only for ru_reset.
        :return: Dict containing: {'exceptions': exceptions, 'ratio': passed_ratio, 'avg': average_startup_time}
        """
        additional_allowed_alarms = []
        if reset_type in ['bts_site_reset', 'bts_power_reset']:
            additional_allowed_alarms = [{'fault_name': 'BTS reset cause',
                                          'alarm_id': 7115,
                                          'fault_id': 4592,
                                          'severity': 'Warning'},
                                         {'fault_name': 'No X2 link available',
                                          'alarm_id': 7107,
                                          'fault_id': 7300,
                                          'severity': 'Major'},
                                         {'fault_name': 'No X2 link available for a specific LTEENB',
                                          'alarm_id': 7107,
                                          'fault_id': 7319,
                                          'severity': 'Major'}]

        self._add_additional_allowed_alarms_to_watcher(additional_allowed_alarms)
        try:
            (passed, failed, passed_run_times) = \
                self._perform_reset_operation_in_loop(bts_id=bts_id, du_id=0,
                                                      runs=runs,
                                                      time_target=time_target,
                                                      timeout=timeout,
                                                      reset_type=reset_type,
                                                      radio_unit=radio_unit,
                                                      end_measure_time=end_measure_time,
                                                      additional_allowed_alarms=additional_allowed_alarms)
        except Exception as e:
            logging.error("Unexpected error occurred: {}".format(repr(e)))
            return
        finally:
            self._delete_additional_allowed_alarms_from_watcher(additional_allowed_alarms)

        return self._get_and_validate_results(passed, failed, passed_run_times, runs,
                                              time_target, target, raise_exception)

    def _add_additional_allowed_alarms_to_watcher(self, additional_allowed_alarms):
        MolerTest.info("Add additional allowed alarms to the alarms watcher", dump=additional_allowed_alarms)
        alarm_verification = self._get_alarm_verification_robot_instance()

        for alarm_params in additional_allowed_alarms:
            alarm_verification.allow_alarm(alarm=alarm_params)

    def _delete_additional_allowed_alarms_from_watcher(self, additional_allowed_alarms):
        MolerTest.info("Delete additional allowed alarms from the alarms watcher", dump=additional_allowed_alarms)
        alarm_verification = self._get_alarm_verification_robot_instance()

        for alarm_params in additional_allowed_alarms:
            alarm_verification.disallow_alarm(alarm=alarm_params)

    def _perform_reset_operation_in_loop(self, bts_id=0, runs=1, time_target=420, timeout=600, du_id=0,
                                         reset_type="bts_site_reset", radio_unit='all_every_second_iteration',
                                         end_measure_time="last_cell_up",
                                         additional_allowed_alarms=[]):

        passed = 0
        failed = 0
        passed_run_times = []

        log_info_to_console("Run {} iterations of {}".format(runs, reset_type))
        for run in range(1, int(runs) + 1):
            current_status = None
            start_time = datetime.datetime.now()
            log_info_to_console('Run: {}'.format(run))
            self.log.start_collecting_btslog(bts_id=bts_id, du_id=du_id)

            _reset_all_rus = None
            _radio_unit_id = None
            if reset_type.lower() == "ru_reset":
                if radio_unit == 'all':
                    _reset_all_rus = True
                elif radio_unit == 'all_every_second_iteration':
                    _reset_all_rus = True if run % 2 == 1 else False
                else:
                    _reset_all_rus = False
                    _radio_unit_id = None if radio_unit == 'random' else radio_unit
                logging.debug("RU reset for {} radio(s), with reset_all_rus={} and radio_unit_id={}".format(
                    radio_unit, _reset_all_rus, _radio_unit_id))

            try:
                run_result = self._measure_single_iteration_start_up_time(bts_id=bts_id,
                                                                          du_id=du_id,
                                                                          time_target=time_to_seconds(time_target),
                                                                          timeout=time_to_seconds(timeout),
                                                                          reset_type=reset_type,
                                                                          reset_all_rus=_reset_all_rus,
                                                                          radio_unit_id=_radio_unit_id,
                                                                          end_measure_time=end_measure_time)
                if isinstance(run_result, datetime.timedelta):
                    current_status = 'PASSED'
                    passed_run_times.append(run_result)
                    current_startup_avg = sum(passed_run_times, datetime.timedelta(0)) / len(passed_run_times)
                    try:
                        self._delete_ims_if_run_passed(start_time)
                        self._delete_ims_if_run_passed(start_time, log_dir=os.path.join(get_log_path(), 'alarms_watchdog'))
                    except FileNotFoundError as e:
                        logging.debug("Unable to delete IMS file: {}".format(e))
                    log_info_to_console('Current start-up time average of successful runs: {}'.
                                        format(current_startup_avg), log_hierarchy=2)
                    log_info_to_console("Run: {} PASSED".format(run), log_hierarchy=2)
                else:
                    current_status = 'FAILED'
                    log_warn_to_console("Run: {} FAILED, start time: {}".format(run, start_time), log_hierarchy=2)
            except Exception as e:
                current_status = 'FAILED'
                log_warn_to_console("Some unexpected exception occurred: {}".format(repr(e)), log_hierarchy=2)
                log_warn_to_console("Please analyze logs!", log_hierarchy=2)
                log_warn_to_console("Run: {} failed, start time: {}".format(run, start_time), log_hierarchy=2)
                self.bbu.wait_for_site_to_be_onair(bts_id=bts_id, du_id=du_id)

            self.cell.wait_for_setup_of_all_cells(bts_id=bts_id, du_id=du_id)
            self.log.stop_collecting_btslog(bts_id=bts_id, du_id=du_id, log_dir=get_log_path(),
                                            file_prefix='run{}'.format(run))
            if current_status == 'PASSED':
                alarm_verification = self._get_alarm_verification_robot_instance()
                alias = self.rest_alias.format(bts_id, du_id)
                for alarm_params in additional_allowed_alarms:
                    if alarm_verification.alarms_watcher[alias].is_alarm_active(**alarm_params):
                        log_warn_to_console("Alarm [{}] should not be visible at the end of iteration".
                                            format(alarm_params['fault_name']),
                                            log_hierarchy=2)
                        log_warn_to_console("Failing iteration", log_hierarchy=2)
                        current_status = 'FAILED'

            if current_status == 'PASSED':
                passed += 1
            if current_status == 'FAILED':
                failed += 1

        return passed, failed, passed_run_times

    @staticmethod
    def _get_and_validate_results(passed, failed, passed_run_times, runs, time_target, target, raise_exception):
        passed_ratio = passed / float(runs)
        average_startup_time = None
        log_info_to_console("Passed/runs ratio: {}".format(passed_ratio))
        exceptions = []
        if len(passed_run_times) > 0:
            average_startup_time = \
                (sum(passed_run_times, datetime.timedelta(0)) / len(passed_run_times)).total_seconds()
            average_startup_time = round(average_startup_time, 1)
            log_info_to_console('Start-up time average of total successful runs: {} sec'.format(average_startup_time))

            if average_startup_time > int(time_target):
                exceptions.append(AverageStartupTargetNotMet("Average startup time {}s exceed presume value {}s"
                                                             .format(average_startup_time, time_target)))

        if passed_ratio < float(target):
            exceptions.append(StartUpTargetNotMet("Runs: {}\n"
                                                  "Failed: {}\n"
                                                  "Ratio: {}\n"
                                                  "Target not met".format(runs, failed, passed_ratio)))

        if raise_exception and exceptions:
            raise StartUpTargetNotMet("\n".join([repr(ex) for ex in exceptions]))
        else:
            return {'exceptions': exceptions, 'ratio': passed_ratio, 'avg': average_startup_time}

    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions(check_steps_end=False)
    @login_logout
    def _measure_single_iteration_start_up_time(self, bts_id=0, time_target=420, timeout=600, du_id=0,
                                                reset_type="bts_site_reset", end_measure_time="last_cell_up",
                                                max_retries=2, reset_all_rus=False, radio_unit_id=None):
        """
        Checks if site fully recovered after bts reset, measures time from the moment first cell goes Offline
        to the moment last cell goes Online, and checks if it meets given time target.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param time_target: Target start-up time in seconds.
        :param timeout: Wait for onAir after bts reset timeout in seconds.
        :param reset_type: Way of reset. Available: bts_site_reset, bts_power_reset, bbmod_reset, ru_reset.
        :param reset_all_rus: If True all available radios are reset. Default False.
        :param radio_unit_id: ID of radio to reset. Applicable only for ru_reset. If None a random radio is chosen.
        :param end_measure_time: first_cell_up or last_cell_up
        :param max_retries: maximum retries if observer timeout
        :return: True if start-up time is shorter than time_target, otherwise False.
        """

        max_time_target = time_target * 1.2
        event_name_before_reset = "cell_status_from_online_to_offline"
        if reset_type == 'ru_reset' and reset_all_rus is False:
            all_ru_ids = self._try_run_coam_method(method=self.ru._get_all_radio_ids,
                                                   bts_id=bts_id, du_id=du_id)['rmod']
            ru_id = random.choice(all_ru_ids) if radio_unit_id is None else radio_unit_id
            cell_ids = []
            cell_ids.extend(self._try_run_coam_method(method=self.cell._get_all_global_cell_ids,
                                                      bts_id=bts_id, du_id=du_id, radio_id=ru_id))
            connected_extensions = self.ru.get_radio_extensions_ids(bts_id, du_id, ru_id)
            for ext_id in connected_extensions:
                cell_ids.extend(self._try_run_coam_method(method=self.cell._get_all_global_cell_ids,
                                                          bts_id=bts_id, du_id=du_id, radio_id=ext_id))
            log_info_to_console("CELL IDs for RMOD-{} and extensions {}: {}".
                                format(ru_id, connected_extensions, cell_ids), log_hierarchy=3)
            event_name_before_reset = "cell_status_from_online_to_failed"
        elif reset_type == 'ru_reset' and reset_all_rus is True:
            cell_ids = self._try_run_coam_method(method=self.cell._get_all_global_cell_ids,
                                                 bts_id=bts_id, du_id=du_id)
            log_info_to_console("All CELL IDs for RMODs: {}".format(cell_ids), log_hierarchy=3)
            event_name_before_reset = "cell_status_from_online_to_failed"
        else:
            cell_ids = self._try_run_coam_method(method=self.cell._get_all_global_cell_ids,
                                                 bts_id=bts_id, du_id=du_id)

        syslog = DeviceFactory.get_device(self.syslog_alias.format(bts_id, du_id))
        self._disconnect_and_connect_to_syslog(syslog=syslog)
        if reset_type != "bts_power_reset":
            first_cell_down = syslog.get_event(event_name=event_name_before_reset,
                                               event_params={
                                                   "till_occurs_times": 1}
                                               )
            first_cell_down.start()

        last_cell_up = syslog.get_event(event_name="cell_status_from_offline_to_online",
                                        event_params={
                                            "till_occurs_times": len(cell_ids)}
                                        )
        last_cell_up.start()

        if reset_type.lower() == "bts_site_reset":
            log_info_to_console("BTS Site reset", log_hierarchy=2)
            self.bbu.reset_bts(bts_id=bts_id, du_id=du_id)
        elif reset_type.lower() == "bts_power_reset":
            log_info_to_console("BTS Power OFF", log_hierarchy=2)
            self.bbu.bts_power_off(bts_id=bts_id, du_id=du_id)
            first_cell_down_result = [{'time': datetime.datetime.now()}]
            log_info_to_console("BTS Power ON", log_hierarchy=2)
            self.bbu.bts_power_on(bts_id=bts_id, du_id=du_id)
        elif reset_type.lower() == "bbmod_reset":
            log_info_to_console("BBMOD reset", log_hierarchy=2)
            self.bbu.reset_abil_via_gui(bts_id=bts_id, du_id=du_id)
        elif reset_type.lower() == "ru_reset" and reset_all_rus:
            log_info_to_console("Reset all Main RUs", log_hierarchy=2)
            self.ru.reset_all_radio_unit(bts_id=bts_id, du_id=du_id, timeout=timeout, force_radio_reset=True)
        elif reset_type.lower() == "ru_reset":
            log_info_to_console("Reset RU{}".format(ru_id), log_hierarchy=2)
            self.ru.reset_radio_unit(bts_id=bts_id, du_id=du_id, radio_unit_id=ru_id,
                                     timeout=timeout, force_radio_reset=True)
        else:
            raise AttributeError("reset_type={} not supported.".format(reset_type))

        if reset_type != "bts_power_reset":
            try:
                first_cell_down_result = first_cell_down.await_done(timeout=60)
            except ConnectionObserverTimeout:
                log_warn_to_console("Observer didn't caught 'Online to Offline/Failed' pattern", log_hierarchy=2)
                log_info_to_console("Waiting for all cells are UP")
                self.cell.wait_for_setup_of_all_cells(bts_id=bts_id, du_id=du_id)
                msg = "Repeating last iteration"
                return self._repeat_iteration(bts_id, du_id, time_target, timeout, max_retries, reset_type, msg,
                                              reset_all_rus=reset_all_rus, radio_unit_id=radio_unit_id)

        try:
            log_info_to_console("Waiting for last cell is UP", log_hierarchy=2)
            last_cell_up_result = last_cell_up.await_done(timeout=timeout)
            log_info_to_console("All cells are UP", log_hierarchy=2)

            cell_set = set()
            cell_ids_set = set(cell_ids)

            for cell_event in last_cell_up_result:
                cell_set.add(int(cell_event['groups'][0][7:]))

            if cell_ids_set == cell_set:
                if end_measure_time == "first_cell_up":
                    start_up_time = last_cell_up_result[0]['time'] - first_cell_down_result[0]['time']
                else:
                    start_up_time = last_cell_up_result[len(cell_ids) - 1]['time'] - first_cell_down_result[0]['time']
                log_info_to_console("Start-up time: {}".format(start_up_time), log_hierarchy=2)
                time_limit = datetime.timedelta(seconds=max_time_target)
                if start_up_time > time_limit:
                    log_warn_to_console("Site start-up time too long({}), getting snapshot".format(start_up_time))
                    self._collect_logs(bts_id=bts_id, du_id=du_id)
                else:
                    return start_up_time
            else:
                log_warn_to_console("Cell ids don't match", log_hierarchy=2)

                logging.debug("Observer caught desired amount of 'offline to online' prints - "
                              "but probably for one of cell print occurred twice")
                logging.debug("Caught cell ids: {}".format(cell_set))
                logging.debug("Configured cell ids: {}".format(cell_ids_set))

                self._recover_bts(bts_id=bts_id, du_id=du_id)
        except ConnectionObserverTimeout:
            try:
                self._try_run_coam_method(method=self.cell.verify_setup_of_all_cells, bts_id=bts_id, du_id=du_id)
                msg = "Syslog did not catch all cells status changes, but all cells " \
                      "are online - repeating last iteration"
                return self._repeat_iteration(bts_id, du_id, time_target, timeout, max_retries, reset_type, msg,
                                              reset_all_rus=reset_all_rus, radio_unit_id=radio_unit_id)
            except IncorrectParameterValue:
                log_warn_to_console("Start-up time exceeded set timeout ({} seconds), getting snapshot"
                                    "".format(timeout), log_hierarchy=2)
                self._recover_bts(bts_id=bts_id, du_id=du_id)

    def _repeat_iteration(self, bts_id, du_id, time_target, timeout, max_retries, reset_type, msg, reset_all_rus=False,
                          radio_unit_id=None):
        if max_retries:
            log_warn_to_console(msg, log_hierarchy=2)
            return self._measure_single_iteration_start_up_time(bts_id=bts_id, du_id=du_id,
                                                                time_target=time_target, timeout=timeout,
                                                                reset_type=reset_type,
                                                                max_retries=max_retries - 1,
                                                                reset_all_rus=reset_all_rus,
                                                                radio_unit_id=radio_unit_id)
        else:
            log_warn_to_console("Max retries achieved - going to the next iteration", log_hierarchy=2)

    def _recover_bts(self, bts_id=0, du_id=0):
        logging.debug("Dump current BTS status")
        self._try_run_coam_method(self.bbu.get_bts_info, bts_id=bts_id, du_id=du_id)
        log_info_to_console("Getting snapshot", log_hierarchy=2)
        self._collect_logs(bts_id=bts_id, du_id=du_id)
        log_warn_to_console("Reset BTS as recovery", log_hierarchy=2)
        self.bbu.reset_bts(bts_id=bts_id, du_id=du_id)
        for i in range(3):
            try:
                log_info_to_console("Waiting for onAir", log_hierarchy=2)
                self.bbu.wait_for_site_to_be_onair(bts_id=0, du_id=0, timeout=600)
                log_info_to_console("Site recovered", log_hierarchy=2)
                logging.debug("Snapshot location: {}".format(
                    self.log.collect_snapshot(bts_id=bts_id, du_id=du_id)))
                break
            except SiteNotOnAir:
                log_warn_to_console("Site not on-air after BTS reset, run all RU power reset as recovery",
                                    log_hierarchy=2)
                self.ru.power_reset_radio_unit(bts_id=bts_id, du_id=du_id)

    def _wait_when_watching_alarms_callback_is_finished(self, interval=30, timeout=15 * 60):
        start_time = round(time.time(), 1)
        alarm_verification = self._get_alarm_verification_robot_instance()
        while alarm_verification.logs_collection_in_progress:
            current_time = round(time.time(), 1)
            if current_time - start_time > timeout:
                logging.debug("Waiting for callback finish timed out.")
                break
            logging.debug("Waiting {} seconds till callback finished".format(interval))
            time.sleep(interval)

    def _collect_logs(self, bts_id=0, du_id=0):
        self._wait_when_watching_alarms_callback_is_finished()
        logging.debug("Snapshot location: {}".format(self.log.collect_snapshot(bts_id=bts_id, du_id=du_id)))

    def _try_run_coam_method(self, method, rerun=2, rerun_interval=10, **kwargs):
        while rerun:
            try:
                result = method(**kwargs)
                return result
            except (AdminApiProcedureFailureException, AdminApiNoResponseException) as e:
                rerun = rerun - 1
                if not rerun:
                    raise e
                logging.debug("COAM REST API exception occurred {}".format(repr(e)))
                logging.debug("Try to rerun method after sleep {} seconds".format(rerun_interval))
                time.sleep(rerun_interval)
                self.disconnect(bts_id=kwargs['bts_is'], du_id=kwargs['du_id'])
                self.connect(bts_id=kwargs['bts_is'], du_id=kwargs['du_id'])

    @staticmethod
    def _disconnect_and_connect_to_syslog(syslog):
        syslog.goto_state('UNIX_REMOTE', keep_state=False)
        time.sleep(1)
        syslog.goto_state('SYSLOG', keep_state=False)

    def measure_time_cell_lock_or_unlock(self, operation="lock", runs=1, time_target=20, timeout=160, bts_id=0,
                                         du_id=0):
        """
        Performs cell lock and unlock given amount of times and check if duration of lock
        and unlock is less than the given time value.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param operation - lock or unlock
        :param runs: Number of runs
        :param time_target: Target lock and unlock time in seconds.
        :param timeout: Wait for value/ regexp found in the syslog.
        :return: average time: Average time lock or unlock
        """
        if operation == "lock":
            runs_time_lock = []
            for run in range(int(runs)):
                logging.info("Run: {} ".format(run))
                lock = self._measure_time_cell_lock_or_unlock(operation=operation, time_target=time_target,
                                                              timeout=timeout, bts_id=bts_id, du_id=du_id)
                runs_time_lock.append(lock)
            average_time = sum(runs_time_lock) / len(runs_time_lock)
            logging.info("Lock cell. Avg {}, Max {}, Runs: {}".format(average_time,
                                                                      max(runs_time_lock), len(runs_time_lock)))

        if operation == "unlock":
            runs_time_unlock = []
            for run in range(int(runs)):
                logging.info("Run: {} ".format(run))
                unlock = self._measure_time_cell_lock_or_unlock(operation=operation, time_target=time_target,
                                                                timeout=timeout, bts_id=bts_id, du_id=du_id)

                runs_time_unlock.append(unlock)
            average_time = sum(runs_time_unlock) / len(runs_time_unlock)
            logging.info("Unlock cell. Avg {}, Max {}, Runs: {}".format(average_time,
                                                                        max(runs_time_unlock), len(runs_time_unlock)))

        return round(average_time, 1)

    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions(check_steps_end=True)
    @login_logout
    def _measure_time_cell_lock_or_unlock(self, operation="lock", bts_id=0, time_target=20, timeout=160, du_id=0):
        """
        Measure time cell lock and unlock and check if it is less than the given time value.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param operation - lock or unlock
        :param time_target: Target lock and unlock time in seconds.
        :param timeout: Wait for value/ regexp found in the syslog.
        :return: None
        """
        err_message = ""
        cell_ids = self.cell._get_all_global_cell_ids(bts_id=bts_id, du_id=du_id)
        syslog = DeviceFactory.get_device(self.syslog_alias.format(bts_id, du_id))
        time_limit = datetime.timedelta(seconds=int(time_target))
        logging.info("Syslog {}".format(syslog))

        if operation == "lock":
            try:
                syslog.goto_state('SYSLOG')
                lock_request_start = syslog.get_event(event_name="accept_download_request_plan",
                                                      event_params={
                                                          "till_occurs_times": 1})
                cell_go_down = syslog.get_event(event_name="cell_status_from_online_to_offline",
                                                event_params={
                                                    "till_occurs_times": 1})
                cell_go_down.start()
                lock_request_start.start()
                self.cell.lock_cell(bts_id=bts_id, cell_id=cell_ids[0], du_id=du_id)
                lock_request_start_result = lock_request_start.await_done(int(timeout))
                cell_go_down_result = cell_go_down.await_done(int(timeout))
                self.cell.unlock_cell(bts_id=bts_id, cell_id=cell_ids[0], du_id=du_id)
                self.cell.wait_for_cell_to_be_onair(cell_id=cell_ids[0])
            except ConnectionObserverTimeout:
                MolerTest.steps_end()
                self.cell.unlock_cell(bts_id=bts_id, cell_id=cell_ids[0], du_id=du_id)
                raise LockCellFailure("Cell was not properly locked")

            lock_cell_request_time = lock_request_start_result[0]['time']
            cell_go_down_time = cell_go_down_result[0]['time']
            operation_time = cell_go_down_time - lock_cell_request_time
            logging.info("Cell lock time duration: {}".format(operation_time))

            if operation_time > time_limit:
                err_message = ("Cell lock time duration {} exceeded max expected time {} seconds"
                               .format(operation_time.total_seconds(), time_target))

        elif operation == "unlock":
            try:
                self.cell.lock_cell(bts_id=bts_id, cell_id=cell_ids[0], du_id=du_id)
                self.cell.wait_for_cell_to_be_locked(cell_id=cell_ids[0])
                syslog.goto_state('SYSLOG')
                unlock_request_start = syslog.get_event(event_name="accept_download_request_plan",
                                                        event_params={
                                                            "till_occurs_times": 1})
                cell_go_up = syslog.get_event(event_name="cell_status_from_offline_to_online",
                                              event_params={
                                                  "till_occurs_times": 1})
                cell_go_up.start()
                unlock_request_start.start()
                self.cell.unlock_cell(bts_id=bts_id, cell_id=cell_ids[0], du_id=du_id)
                unlock_request_start_result = unlock_request_start.await_done(int(timeout))
                cell_go_up_result = cell_go_up.await_done(int(timeout))
            except ConnectionObserverTimeout:
                MolerTest.steps_end()
                raise UnlockCellFailure("Cell was not properly unlocked")

            unlock_cell_request_time = unlock_request_start_result[0]['time']
            cell_go_up_time = cell_go_up_result[0]['time']
            operation_time = cell_go_up_time - unlock_cell_request_time
            logging.info("Cell unlock time duration: {}".format(operation_time))

            if operation_time > time_limit:
                err_message = ("Cell unlock time duration {} exceeded max expected time {} seconds"
                               .format(operation_time.total_seconds(), time_target))

        if err_message != "":
            MolerTest.steps_end()
            raise LockUnlockTargetNotMet(err_message)
        else:
            MolerTest.steps_end()
            return operation_time.total_seconds()

    @login_logout
    def measure_cell_lock_unlock_time_via_gui(self, bts_id=0, du_id=0, runs=1, target=1, time_target=40, timeout=160,
                                              raise_exception=True):
        """
        Performs cell lock/unlock given amount of times, checks if site fully recovered and measures operation time,
        then checks if results meet given target.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param runs: Number of runs
        :param target: passed/all runs ratio
        :param time_target: Target lock/unlock operation time in seconds.
        :param timeout: Wait for value/ regexp found in the syslog.
        :param raise_exception: True/False - raise LockUnlockTargetNotMet exception if avg/ratio not met targets
        :return: Dict containing: avg, ratio, exceptions.
        """
        passed = 0
        failed = 0
        passed_run_times = []
        cell_ids = self.cell._get_all_global_cell_ids(bts_id=bts_id, du_id=du_id)
        for run in range(1, int(runs) + 1):
            logging.info("Run: {} ".format(run))
            cell_id = random.choice(cell_ids)
            logging.info("Selected cell ID: {}".format(cell_id))
            run_result = self._measure_cell_lock_unlock_time_via_gui(time_target=time_target, timeout=timeout,
                                                                     bts_id=bts_id, du_id=du_id, cell_id=cell_id)
            if isinstance(run_result, datetime.timedelta):
                passed += 1
                passed_run_times.append(run_result)
                current_lock_unlock_avg = sum(passed_run_times, datetime.timedelta(0)) / len(passed_run_times)
                logging.info("Run: {} passed. Cell lock/unlock time: {} seconds".format(run, run_result))
                logging.info('Current lock/unlock time average of successful runs: {}'.format(current_lock_unlock_avg))
            else:
                logging.warning("Run: {} failed".format(run))
                failed += 1
        passed_ratio = passed / float(runs)
        average_lock_unlock_time = None
        logging.info("Passed/runs ratio: {}".format(passed_ratio))
        exceptions = []
        if len(passed_run_times) > 0:
            average_lock_unlock_time = \
                (sum(passed_run_times, datetime.timedelta(0)) / len(passed_run_times)).total_seconds()
            logging.info('Lock/unlock time average of total successful runs: {} sec'.format(average_lock_unlock_time))
            if average_lock_unlock_time > int(time_target):
                exceptions.append(LockUnlockTargetNotMet("Average lock/unlock time {}s exceed presume value {}s"
                                                         .format(average_lock_unlock_time, time_target)))
        if passed_ratio < float(target):
            exceptions.append(LockUnlockTargetNotMet("Runs: {}; "
                                                     "Failed: {}; "
                                                     "Ratio: {}; "
                                                     "Target not met".format(runs, failed, passed_ratio)))
        if raise_exception and exceptions:
            raise LockUnlockTargetNotMet("\n".join([repr(e) for e in exceptions]))
        else:
            return {'exceptions': exceptions, 'ratio': passed_ratio, 'avg': round(average_lock_unlock_time, 1)}

    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def _measure_cell_lock_unlock_time_via_gui(self, bts_id=0, du_id=0, cell_id=1, time_target=40, timeout=160):
        """
        Checks if site fully recovered after cell lock/unlock operation, measures time from the moment first cell goes
        Offline to the moment last cell goes Online, and checks if it meets given time target.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id: id of cell to be locked and unlocked.
        :param time_target: Target cell lock/unlock operation time in seconds.
        :param timeout: Wait for value/ regexp found in the syslog.
        :return: Cell lock/unlock time if passed, otherwise None.
        """
        self.log.start_collecting_syslog(bts_id, du_id)
        syslog = DeviceFactory.get_device(self.syslog_alias.format(bts_id, du_id))
        self.log.start_collecting_syslog(bts_id, du_id)
        logging.info("Syslog {}".format(syslog))
        syslog.goto_state('SYSLOG')
        try:
            cell_go_down = syslog.get_event(event_name="cell_status_from_online_to_offline",
                                            event_params={
                                                "till_occurs_times": 1})
            cell_go_down.start()
            self.cell.lock_cell_via_gui(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            cell_go_down_result = cell_go_down.await_done(int(timeout))
        except ConnectionObserverTimeout:
            MolerTest.steps_end()
            self.cell.unlock_cell_via_gui(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            logging.warning(LockCellFailure("Cell was not properly locked"))
            return None
        try:
            unlock_request_start = syslog.get_event(event_name="accept_download_request_plan",
                                                    event_params={
                                                        "till_occurs_times": 1})
            cell_go_up = syslog.get_event(event_name="cell_status_from_offline_to_online",
                                          event_params={
                                              "till_occurs_times": 1})
            unlock_request_start.start()
            cell_go_up.start()
            start_unlock = datetime.datetime.now()
            self.cell.unlock_cell_via_gui(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            unlock_request_start_result = unlock_request_start.await_done(int(timeout))
            cell_go_up_result = cell_go_up.await_done(int(timeout))
        except ConnectionObserverTimeout:
            MolerTest.steps_end()
            logging.warning(UnlockCellFailure("Cell was not properly unlocked"))
            return None
        cell_go_down_time = cell_go_down_result[0]['time']
        logging.info("Cell lock time: {}".format(cell_go_down_time))
        logging.info("Start Cell unlock time: {}".format(start_unlock))
        unlock_request_start_time = unlock_request_start_result[0]['time']
        logging.info("Cell unlock request time: {}".format(unlock_request_start_time))
        cell_go_up_time = cell_go_up_result[0]['time']
        logging.info("Cell unlock time: {}".format(cell_go_up_time))
        time_limit = datetime.timedelta(seconds=int(time_target))
        click_time = unlock_request_start_time - start_unlock
        cell_lock_unlock_time = cell_go_up_time - cell_go_down_time - click_time
        err_message_list = []
        if cell_lock_unlock_time > time_limit:
            err_message_list.append("Cell lock/unlock time duration {} exceeded max expected time {} seconds"
                                    .format(cell_lock_unlock_time.total_seconds(), time_target))
        if len(err_message_list) > 0:
            MolerTest.steps_end()
            logging.warning(LockUnlockTargetNotMet(err_message_list))
            return None
        self.log.stop_collecting_syslog(bts_id, du_id)
        MolerTest.steps_end()
        return cell_lock_unlock_time

    @login_logout
    def measure_cell_block_unblock_time(self, bts_id=0, du_id=0, runs=1, block_target=12, unblock_target=15,
                                        timeout=160):
        """
        Performs cell block/unblock given amount of times, checks if site fully recovered and measures operation time,
        then checks if results meet given target.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param runs: Number of runs
        :param block_target: Target block operation time in seconds.
        :param unblock_target: Target unblock operation time in seconds.
        :param timeout: Wait for value/ regexp found in the syslog.
        :return: Dict containing: avg, ratio, exceptions.
        """
        passed_run_times = {
            'block': [],
            'unblock': [],
        }
        run_times = {
            'block': {
                'duration': [],
                'passed': 0,
                'failed': 0,
                'average': 0,
                'ratio': 0.0
            },
            'unblock': {
                'duration': [],
                'passed': 0,
                'failed': 0,
                'average': 0,
                'ratio': 0.0
            },
        }

        additional_allowed_alarms = [{'fault_name': 'Cell blocked',
                                      'alarm_id': 7102,
                                      'fault_id': 49,
                                      'severity': 'Critical'}]
        self._add_additional_allowed_alarms_to_watcher(additional_allowed_alarms)

        block_target = datetime.timedelta(seconds=int(block_target))
        unblock_target = datetime.timedelta(seconds=int(unblock_target))
        cell_ids = self.cell._get_all_global_cell_ids(bts_id=bts_id, du_id=du_id)
        for run in range(1, int(runs) + 1):
            log_info_to_console(msg="Run: {} ".format(run))
            self.log.start_collecting_btslog(bts_id=bts_id, du_id=du_id)
            cell_id = random.choice(cell_ids)
            log_info_to_console(msg="Selected cell ID: {}".format(cell_id), log_hierarchy=2)
            run_result = self._measure_cell_block_unblock_time(timeout=timeout,
                                                               bts_id=bts_id,
                                                               du_id=du_id,
                                                               cell_id=cell_id)

            self._check_block_unblock_results(run_times, passed_run_times, run_result['block_duration'],
                                              block_target, run, mode='block')
            self._check_block_unblock_results(run_times, passed_run_times, run_result['unblock_duration'],
                                              unblock_target, run, mode='unblock')

            self.log.stop_collecting_btslog(bts_id=bts_id, du_id=du_id, log_dir=get_log_path(),
                                            file_prefix='run{}'.format(run))

        self._delete_additional_allowed_alarms_from_watcher(additional_allowed_alarms)

        for mode in run_times:
            run_times[mode]['ratio'] = run_times[mode]['passed'] / float(runs)
            MolerTest.info("Summary of {} procedure".format(mode))
            MolerTest.info("Total Runs: {}\n"
                           "Passed: {}\n"
                           "Failed: {}\n"
                           "Ratio: {}\n"
                           "Average time {}\n"
                           "Min time {}\n"
                           "Max time {}".format(runs, run_times[mode]['passed'], run_times[mode]['failed'],
                                                run_times[mode]['ratio'], run_times[mode]['average'],
                                                min(run_times[mode]['duration']), max(run_times[mode]['duration'])))

        return {'block': {'ratio': run_times['block']['ratio'], 'avg': round(run_times['block']['average'], 1)},
                'unblock': {'ratio': run_times['unblock']['ratio'], 'avg': round(run_times['unblock']['average'], 1)}}

    @staticmethod
    def _check_block_unblock_results(run_times, passed_run_times, run_result, time_limit, run, mode):
        if isinstance(run_result, datetime.timedelta):
            run_times[mode]['duration'].append(run_result)
            if run_result <= time_limit:
                run_times[mode]['passed'] += 1
                passed_run_times[mode].append(run_result)
                run_times[mode]['average'] = \
                    (sum(passed_run_times[mode], datetime.timedelta(0)) / len(passed_run_times[mode])).total_seconds()
                log_info_to_console("Run: {} - {} passed.".format(run, mode.upper()), log_hierarchy=2)
                log_info_to_console('Current {} time average of successful runs: {}'.
                                    format(mode.upper(), run_times[mode]['average']), log_hierarchy=2)
            else:
                log_warn_to_console("Run: {} - {} failed".format(run, mode.upper()), log_hierarchy=2)
                run_times[mode]['failed'] += 1

            MolerTest.info("Cell {} time: {} seconds".format(mode.upper(), run_result))

        else:
            log_warn_to_console("Cannot measure {} time due to issue with block/unblock".format(mode.upper()),
                                log_hierarchy=2)
            log_warn_to_console("Run: {} - {} failed".format(run, mode.upper()), log_hierarchy=2)
            run_times[mode]['failed'] += 1

    @load_moler_configuration_from_tl()
    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def _measure_cell_block_unblock_time(self, bts_id=0, du_id=0, cell_id=1, timeout=160, block_fault_id=49):
        """
        Checks if site fully recovered after cell lock/unlock operation, measures time from the moment first cell goes
        Offline to the moment last cell goes Online, and checks if it meets given time target.
        :param bts_id: BTS id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :param cell_id: id of cell to be blocked and unblocked.
        :param timeout: Wait for value/ regexp found in the syslog.
        :return: Cell block/unblock time if passed, otherwise None.

        Block alarm:
                 "severity": "Critical",
                 "alarmId": 7102,
                 "faultId": 49,
        """
        results = dict.fromkeys(['block_unblock_duration', 'block_duration', 'unblock_duration'])
        self.log.start_collecting_syslog(bts_id, du_id)
        syslog = DeviceFactory.get_device(self.syslog_alias.format(bts_id, du_id))
        syslog.goto_state('SYSLOG')
        try:
            cell_go_down = syslog.get_event(event_name="cell_status_from_online_to_offline",
                                            event_params={
                                                "till_occurs_times": 1})

            # INF/SysAdapter/URI/GW, [urigw::statemachine::SessionEstablishedState]
            # decoded /MRBTS-1/RAT-1/URI-1/SESSION-127153/BLOCK_IND-0 trying to commit
            re_block_request = r'SysAdapter.*\/BLOCK_IND-\d+ trying to commit'
            block_request = syslog.get_event(event_name="wait4",
                                             event_params={
                                                 "detect_patterns": [re_block_request],
                                                 "till_occurs_times": 1})
            cell_go_down.start()
            block_request.start()

            log_info_to_console(msg='Block cell {}'.format(cell_id), log_hierarchy=2)
            self.cell.block_cell(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            start_waiting_for_alarm_timestamp = datetime.datetime.now()
            log_info_to_console(msg="Wait for 'Cell blocked' alarm activation", log_hierarchy=2)
            self.alarm.wait_for_alarm_activation(fault_id=block_fault_id)
            log_info_to_console(msg="'Cell blocked' alarm appeared", log_hierarchy=2)
            end_waiting_for_alarm_timestamp = datetime.datetime.now()

            block_request_result = block_request.await_done(15)
            cell_go_down_result = cell_go_down.await_done(int(timeout))

            block_duration = cell_go_down_result[0]['time'] - block_request_result[0]['time']
            log_info_to_console(msg="Block duration: {}".format(block_duration), log_hierarchy=2)
            awaiting_for_alarm_activation = end_waiting_for_alarm_timestamp - start_waiting_for_alarm_timestamp
            MolerTest.info("Block duration(measured to cell goes to offline state) {}".format(block_duration))
            MolerTest.info("Alarm occurred after {}".format(awaiting_for_alarm_activation))
        except ConnectionObserverTimeout:
            MolerTest.steps_end()
            try:
                self.cell.verify_cell_is_blocked(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
                MolerTest.warning("Cell is blocked but 'print' was not caught by moler syslog")
                # TODO rerun iteration?
                self.cell.unblock_cell(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            except IncorrectStatuses:
                MolerTest.warning("Cell was not properly blocked")

            return results
        try:
            cell_go_up = syslog.get_event(event_name="cell_status_from_offline_to_online",
                                          event_params={
                                              "till_occurs_times": 1})

            # INF/SysAdapter/URI/GW, [urigw::statemachine::SessionEstablishedState]
            # decoded /MRBTS-1/RAT-1/URI-1/SESSION-159953/UNBLOCK_IND-0 trying to commit
            re_unblock_request = r'SysAdapter.*\/UNBLOCK_IND-\d+ trying to commit'
            unblock_request = syslog.get_event(event_name="wait4",
                                               event_params={
                                                   "detect_patterns": [re_unblock_request],
                                                   "till_occurs_times": 1})
            unblock_request.start()
            cell_go_up.start()

            log_info_to_console(msg='Unblock cell {}'.format(cell_id), log_hierarchy=2)
            self.cell.unblock_cell(bts_id=bts_id, cell_id=cell_id, du_id=du_id)
            start_waiting_for_alarm_timestamp = datetime.datetime.now()
            log_info_to_console(msg="Wait for 'Cell blocked' alarm deactivation", log_hierarchy=2)
            self.alarm.wait_for_alarm_deactivation(fault_id=block_fault_id)
            log_info_to_console(msg="'Cell blocked' alarm disappeared", log_hierarchy=2)
            end_waiting_for_alarm_timestamp = datetime.datetime.now()

            unblock_request_result = unblock_request.await_done(15)
            cell_go_up_result = cell_go_up.await_done(int(timeout))

            unblock_duration = cell_go_up_result[0]['time'] - unblock_request_result[0]['time']
            log_info_to_console(msg="Unblock duration: {}".format(unblock_duration), log_hierarchy=2)
            awaiting_for_alarm_deactivation = end_waiting_for_alarm_timestamp - start_waiting_for_alarm_timestamp
            MolerTest.info("Unblock duration(measured to cell goes to online state) {}".format(unblock_duration))
            MolerTest.info("Alarm disappeared after {}".format(awaiting_for_alarm_deactivation))
        except ConnectionObserverTimeout:
            MolerTest.steps_end()
            MolerTest.warning("Cell was not properly unblocked")
            return results

        results['block_unblock_duration'] = block_duration + unblock_duration
        results['block_duration'] = block_duration
        results['unblock_duration'] = unblock_duration

        self.log.stop_collecting_syslog(bts_id, du_id)
        MolerTest.steps_end()
        return results

    @staticmethod
    def _delete_ims_if_run_passed(iteration_start_time, log_dir=None):
        """
        Delete ims2 logs if creation time is bigger than iteration start time
        :param iteration_start_time: datetime() object, time when iteration started
        :return: None
        """
        if log_dir is None:
            log_dir = get_builtin_value('OUTPUT_DIR')
        dir_files = os.listdir(log_dir)
        ims2_files_pattern = re.compile(r'.*ims2')
        for dir_file in dir_files:
            if ims2_files_pattern.match(dir_file):
                path_to_file = os.path.join(log_dir, dir_file)
                creation_time = os.stat(path_to_file).st_ctime
                iter_start_time_timestamp = time.mktime(iteration_start_time.timetuple())
                if creation_time > iter_start_time_timestamp:
                    os.remove(path_to_file)
                    logging.debug("Removed ims file: {}".format(path_to_file))

    @abstractmethod
    def _get_alarm_verification_robot_instance(self):
        pass


