class GnbMeasureStartup(GenericMeasureStartup):
    """Class contains keywords for gNB combined from different keyword types e.g. alarm and cell"""

    bts_type = 'GNB'

    def __init__(self):
        """
        Constructor of Gnb class.
        """
        super(GnbMeasureStartup, self).__init__(bts_type=GnbMeasureStartup.bts_type,
                                                bbu=GnbDuOperations(),
                                                alarm=GnbAlarmVerification(),
                                                cell=GnbCellOperations(),
                                                log=GnbBtslogCollector(),
                                                ru=GnbRuOperations())

    def _get_alarm_verification_robot_instance(self):
        """
        Get robot instance of GnbAlarmVerification class.
        :return: GnbAlarmVerification object
        """
        library_path = 'taf.rfrl.bts.devices.du.alarm_verification.GnbAlarmVerification'
        return get_robot_builtin_instance_and_import_if_needed('gnbalarm', library_path)
